public str getName()
{
    return fieldPName(CustDirectDebitMandate, SignatureLocation);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by SignatureLocation
    {
        if (! ret.in(custDirectDebitMandate.SignatureLocation))
        {
            ret.add(custDirectDebitMandate.SignatureLocation);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, SignatureLocation));
    qbr.value(queryValue(_value));
}
